// The player's games folders over real files: shortcuts generated byte by byte (MS-SHLLINK) and
// read back, malformed ones refused, what the filter rule keeps out, and each OS's scan.
#include "library/game_folder.hpp"
#include "library/shell_link.hpp"

#include <algorithm>
#include <cstdint>
#include <cstdio>
#include <filesystem>
#include <fstream>
#include <string>
#include <vector>

#include "check.hpp"
