namespace {

namespace fs = std::filesystem;
namespace folder = opensu::library::folder;
namespace own = opensu::library::own;
using folder::Host;
using opensu::library::parseShellLink;
using opensu::library::ShellLink;
using opensu::test::expect;
using opensu::test::LinkFields;
using opensu::test::shellLinkBytes;

void write(const fs::path& file, const std::string& text = "x") {
    fs::create_directories(file.parent_path());
    std::ofstream out{file, std::ios::binary};
    out << text;
}

void writeLink(const fs::path& file, const LinkFields& fields) {
    const std::vector<std::uint8_t> bytes = shellLinkBytes(fields);
    write(file, std::string{bytes.begin(), bytes.end()});
}

/// A path as a shortcut written by Windows names it here.
std::string windowsWritten(const fs::path& file) {
#ifdef _WIN32
    return file.string();
#else
    std::string path = "Z:" + file.string();
    std::ranges::replace(path, '/', '\\');
    return path;
#endif
}

/// The shortcut of `fields`, read back.
ShellLink parsed(const LinkFields& fields) {
    std::optional<ShellLink> link = parseShellLink(shellLinkBytes(fields));
    if (!link) {
        expect(false, "a shortcut reads");
        return {};
    }
    return *std::move(link);
}

std::vector<std::string> titlesOf(const std::vector<own::Entry>& games) {
    std::vector<std::string> titles;
    titles.reserve(games.size());
    for (const own::Entry& game : games) {
        titles.push_back(game.title);
    }
    std::ranges::sort(titles);
    return titles;
}

void linkFieldsReadBack() {
    const LinkFields fields{.target = R"(C:\Games\Dino Crisis 2\DINO2.exe)",
                            .arguments = "-window -skip \"a b\"",
                            .workingDirectory = R"(C:\Games\Dino Crisis 2)",
                            .iconLocation = R"(C:\Games\Dino Crisis 2\dino.ico)",
                            .iconIndex = 3,
                            .description = "A game"};
    for (const bool unicode : {true, false}) {
        LinkFields each = fields;
        each.unicode = unicode;
        const ShellLink link = parsed(each);
        expect(link.target == fields.target, "its target");
        expect(link.arguments == fields.arguments, "its arguments");
        expect(link.workingDirectory == fields.workingDirectory, "its working folder");
        expect(link.iconLocation == fields.iconLocation && link.iconIndex == 3, "its icon");
        expect(link.description == fields.description, "its comment");
    }
    LinkFields suffixed = fields;
    suffixed.target = R"(C:\Games\)";
    suffixed.suffix = R"(Dino Crisis 2\DINO2.exe)";
    expect(parsed(suffixed).target == fields.target,
           "the common path suffix follows the base path");
    LinkFields negative = fields;
    negative.iconIndex = -101;
    expect(parsed(negative).iconIndex == -101, "a resource id is negative");
    LinkFields wide = fields;
    wide.target = "C:\\Oyunlar\\\xC5\x9E"
                  "eker\\game.exe";
    expect(parsed(wide).target == wide.target, "Unicode paths survive");
}

void brokenLinksEndTheRead() {
    const LinkFields fields{.target = R"(C:\a\b.exe)",
                            .arguments = "-x",
                            .workingDirectory = R"(C:\a)",
                            .iconLocation = R"(C:\a\i.ico)",
                            .iconIndex = 0,
                            .description = "d"};
    const std::vector<std::uint8_t> whole = shellLinkBytes(fields);
    expect(!parseShellLink({}).has_value(), "no bytes are no link");
    for (std::size_t size = 0; size < whole.size(); ++size) {
        const auto cut = parseShellLink(std::span{whole}.first(size));
        expect(size >= 0x4C || !cut.has_value(), "a cut header is no link");
    }
    std::vector<std::uint8_t> wrong = whole;
    wrong[4] ^= 0xFFU;
    expect(!parseShellLink(wrong).has_value(), "another class id is no link");
    // Every byte set to each extreme in turn: the read ends, whatever it finds.
    for (std::size_t at = 0; at < whole.size(); ++at) {
        for (const std::uint8_t value : {std::uint8_t{0x00}, std::uint8_t{0xFF}}) {
            std::vector<std::uint8_t> mangled = whole;
            mangled[at] = value;
            static_cast<void>(parseShellLink(mangled));
        }
    }
}

void theRuleKeepsToolsOut() {
    for (const char* tool : {"unins000",
                             "Uninstall Dino Crisis 2",
                             "setup",
                             "Setup_Game",
                             "vcredist_x64",
                             "VC_redist.x64",
                             "DXSETUP",
                             "UnityCrashHandler64",
                             "CrashReportClient",
                             "crash_reporter",
                             "Steam",
                             "GalaxyClient",
                             "EpicGamesLauncher",
                             "UE4PrereqSetup_x64",
                             "Launcher",
                             "dotNetFx40",
                             "EasyAntiCheat_Setup",
                             "Battle.net",
                             "game-updater",
                             "BEService"}) {
        expect(folder::notAGame(tool), tool);
    }
    for (const char* game : {"Dino Crisis 2", "Crash Bandicoot N. Sane Trilogy", "SteamWorld Dig",
                             "Origin of the Species", "Portal 2", "Update Quest", "DINO2"}) {
        expect(!folder::notAGame(game), game);
    }
}

void windowsFolder(const fs::path& root) {
    const fs::path games = root / "windows";
    const fs::path dino = games / "Dino Crisis 2" / "DINO2.exe";
    write(dino);
    write(games / "Dino Crisis 2" / "unins000.exe");
    write(games / "Dino Crisis 2" / "config.dat");
    write(games / "Space Game" / "Binaries" / "deep.exe");
    write(games / "Space Game" / "space.exe");
    write(games / "Space Game" / "UnityCrashHandler64.exe");
    write(games / "Redist" / "vcredist_x64.exe");
    write(games / "_CommonRedist" / "game.exe");
    write(games / "Tools" / "setup.exe");
    write(games / "stray.txt");
    const fs::path shortcuts = games / "Other";
    write(shortcuts / "real.exe");
    writeLink(games / "My Favourite.lnk",
              LinkFields{.target = windowsWritten(shortcuts / "real.exe"),
                         .arguments = "-window \"two words\"",
                         .workingDirectory = windowsWritten(shortcuts),
                         .iconLocation = windowsWritten(shortcuts / "real.ico"),
                         .iconIndex = 2});
    writeLink(games / "Uninstall Other.lnk",
              LinkFields{.target = windowsWritten(shortcuts / "real.exe")});
    writeLink(games / "Gone.lnk", LinkFields{.target = windowsWritten(games / "gone.exe")});
    writeLink(games / "Readme.lnk", LinkFields{.target = windowsWritten(games / "stray.txt")});
    write(games / "Broken.lnk", "not a link");
    write(games / "Site.url", "[InternetShortcut]\r\nURL=https://example.com/\r\n");
    write(games / "Store Game.url",
          "[InternetShortcut]\r\nURL=steam://rungameid/4249140\r\nIconFile=" +
              windowsWritten(shortcuts / "real.ico") + "\r\nIconIndex=1\r\n");

    const std::vector<own::Entry> found = folder::scan(games, Host::Windows);
    expect(titlesOf(found) == std::vector<std::string>{"Dino Crisis 2", "My Favourite",
                                                       "Space Game", "Store Game"},
           "shortcuts and one program a subfolder, nothing the rule keeps out");
    const auto named = [&found](const std::string& title) {
        return *std::ranges::find(found, title, &own::Entry::title);
    };
    const own::Entry favourite = named("My Favourite");
    expect(favourite.file == shortcuts / "real.exe", "a shortcut starts its target");
    expect(favourite.args == std::vector<std::string>{"-window", "two words"},
           "with its arguments");
    expect(favourite.workingDirectory == shortcuts, "in its working folder");
    expect(favourite.icon == shortcuts / "real.ico" && favourite.iconIndex == 2, "with its icon");
    expect(favourite.origin == own::Origin::Folder, "a game of the folder");
    expect(named("Dino Crisis 2").file == dino, "the program, not the uninstaller");
    expect(named("Space Game").file == games / "Space Game" / "space.exe",
           "the program named like its folder, not one further down");
    const own::Entry store = named("Store Game");
    expect(store.steamAppId == "4249140" && !store.command.empty() &&
               store.command.back() == "steam://rungameid/4249140",
           "a Steam link is its app, opened by the system");
    expect(store.icon == shortcuts / "real.ico" && store.iconIndex == 1, "a .url's icon");
    const std::vector<own::Entry> again = folder::scan(games, Host::Windows);
    expect(std::ranges::equal(found, again), "a scan comes out the same, ids and all");

    fs::remove(dino);
    expect(titlesOf(folder::scan(games, Host::Windows)) ==
               std::vector<std::string>{"My Favourite", "Space Game", "Store Game"},
           "a file that goes takes its game with it");
    expect(folder::scan(root / "not-there", Host::Windows).empty(), "no folder holds no games");
}

void aShortcutBesideItsFolderIsOneGame(const fs::path& root) {
    const fs::path games = root / "twice";
    const fs::path exe = games / "Dino Crisis 2" / "DINO2.exe";
    write(exe);
    writeLink(games / "Dino.lnk", LinkFields{.target = windowsWritten(exe)});
    const std::vector<own::Entry> found = folder::scan(games, Host::Windows);
    expect(titlesOf(found) == std::vector<std::string>{"Dino"},
           "the shortcut and the program it starts are one game, by the shortcut's name");
}

#ifndef _WIN32
void writeProgram(const fs::path& file, const std::string& text) {
    write(file, text);
    fs::permissions(file, fs::perms::owner_all);
}

void linuxFolder(const fs::path& root) {
    const fs::path games = root / "linux";
    const std::string elf = std::string{"\x7F"} + "ELF\x02\x01\x01";
    writeProgram(games / "nebula", elf);
    writeProgram(games / "notes", "plain text with an execute bit");
    writeProgram(games / "libgame.so", elf);
    write(games / "Run Me.desktop",
          "[Desktop Entry]\nType=Application\nName=Desktop Name\nExec=\"/opt/my game/run\" %U\n"
          "Path=/opt/my game\nIcon=mygame\n");
    write(games / "Hidden.desktop",
          "[Desktop Entry]\nType=Application\nName=H\nExec=h\nNoDisplay=true\n");
    write(games / "Link.desktop", "[Desktop Entry]\nType=Link\nName=L\nURL=https://x/\n");
    write(games / "Steam One.desktop",
          "[Desktop Entry]\nType=Application\nName=Stored\nExec=steam steam://rungameid/620\n");
    writeProgram(games / "Sub Game" / "start.sh", "#!/bin/sh\n");
    writeProgram(games / "Sub Game" / "uninstall.sh", "#!/bin/sh\n");
    write(games / "Wine Game" / "wine.exe");
    writeProgram(games / "aaa.sh", "#!/bin/sh\n");
    write(games / "zzz.desktop", "[Desktop Entry]\nType=Application\nName=Twin\nExec=" +
                                     (games / "aaa.sh").string() + " %U\n");

    const std::vector<own::Entry> found = folder::scan(games, Host::Linux);
    expect(titlesOf(found) == std::vector<std::string>{"Desktop Name", "Nebula", "Stored",
                                                       "Sub Game", "Twin", "Wine Game"},
           ".desktop entries and programs, a program its entry starts once; a text file with the "
           "bit set is none");
    const own::Entry desktop = *std::ranges::find(found, "Desktop Name", &own::Entry::title);
    expect(desktop.command == std::vector<std::string>{"/opt/my game/run"},
           "Exec without its field codes, its quotes honoured");
    expect(desktop.workingDirectory == "/opt/my game" && desktop.icon == "mygame", "Path and Icon");
    expect(std::ranges::find(found, "Stored", &own::Entry::title)->steamAppId == "620",
           "a Steam entry is its app");
}

void macFolder(const fs::path& root) {
    const fs::path games = root / "mac";
    const fs::path app = games / "Sub" / "Grand.app";
    write(app / "Contents" / "Info.plist",
          "<plist><dict><key>CFBundleExecutable</key><string>grand</string>"
          "<key>CFBundleName</key><string>Grand Game</string>"
          "<key>CFBundleIconFile</key><string>GrandIcon</string></dict></plist>");
    writeProgram(app / "Contents" / "MacOS" / "grand", "#!/bin/sh\n");
    writeProgram(games / "Plain.app" / "Contents" / "MacOS" / "Plain", "#!/bin/sh\n");
    writeProgram(games / "Uninstaller.app" / "Contents" / "MacOS" / "Uninstaller", "#!/bin/sh\n");
    const std::vector<own::Entry> found = folder::scan(games, Host::Mac);
    expect(titlesOf(found) == std::vector<std::string>{"Grand Game", "Plain"},
           ".app bundles here and one folder down");
    const own::Entry grand = *std::ranges::find(found, "Grand Game", &own::Entry::title);
    expect(grand.file == app / "Contents" / "MacOS" / "grand", "its bundle's executable");
    expect(grand.icon == app / "Contents" / "Resources" / "GrandIcon.icns", "its bundle's icon");
}
#endif

void aFolderGameLaunches(const fs::path& root) {
    const fs::path games = root / "launch";
    const fs::path exe = games / "Dino Crisis 2" / "DINO2.exe";
    write(exe);
    const std::vector<own::Entry> found = folder::scan(games, Host::Windows);
    expect(found.size() == 1, "one game");
    const opensu::library::Game game = own::gameOf(found.front());
    expect(game.id == "own:" + found.front().id && game.sourceId == found.front().id,
           "a game of the player's own");
    expect(game.fromGameFolder, "it says it came from a folder");
    expect(game.launch.program == exe.string(), "started from its file");

    const own::Records records{root / "records.json"};
    own::Provider provider{records, root / "no-lutris", {games}};
    const std::vector<opensu::library::Game> listed = provider.list(std::stop_token{});
    expect(listed.size() == 1 && listed.front().id == game.id,
           "the provider lists a folder's games");
    records.add(own::Entry{.id = {}, .title = "Kept", .file = exe});
    expect(provider.list(std::stop_token{}).size() == 1,
           "a game added by hand is not listed twice");
}

} // namespace

int main() try {
    const opensu::test::ScratchDir scratch{OPENSU_TEST_SCRATCH, "game_folder"};
    const fs::path& root = scratch.path();
    linkFieldsReadBack();
    brokenLinksEndTheRead();
    theRuleKeepsToolsOut();
    windowsFolder(root);
    aShortcutBesideItsFolderIsOneGame(root);
#ifndef _WIN32
    linuxFolder(root);
    macFolder(root);
#endif
    aFolderGameLaunches(root);
    std::printf("game_folder: all checks passed\n");
    return 0;
} catch (...) {
    return opensu::test::escaped();
}
